CREATE TABLE IF NOT EXISTS decision_context_snapshots (workspace_id text NOT NULL,id text NOT NULL,schema_version integer NOT NULL,snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,id));
CREATE TABLE IF NOT EXISTS decision_records (workspace_id text NOT NULL,id text NOT NULL,customer_id text NOT NULL,current_customer_id text,radar_id text NOT NULL,definition_version integer NOT NULL,model_version_id text NOT NULL,score_batch_id text NOT NULL,score_cutoff timestamptz NOT NULL,opportunity_batch_id text,opportunity_row_id text,target_outcome_definition_id text NOT NULL,policy_version text NOT NULL,trigger_source text NOT NULL,selected_action_type text NOT NULL,selected_action_version integer NOT NULL DEFAULT 1,context_snapshot_id text NOT NULL,decision_batch_id text,correlation_id text NOT NULL,idempotency_key text NOT NULL,reward_window_end timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,id),UNIQUE(workspace_id,idempotency_key),FOREIGN KEY(workspace_id,customer_id) REFERENCES customers(workspace_id,id) ON DELETE RESTRICT,FOREIGN KEY(workspace_id,radar_id) REFERENCES radars(workspace_id,id) ON DELETE RESTRICT,FOREIGN KEY(workspace_id,model_version_id) REFERENCES radar_model_versions(workspace_id,id) ON DELETE RESTRICT,FOREIGN KEY(workspace_id,context_snapshot_id) REFERENCES decision_context_snapshots(workspace_id,id) ON DELETE RESTRICT,FOREIGN KEY(workspace_id,target_outcome_definition_id) REFERENCES outcome_definitions(workspace_id,id) ON DELETE RESTRICT,CHECK(selected_action_type IN ('do_nothing','send_audience')));
CREATE INDEX IF NOT EXISTS decision_records_list_idx ON decision_records(workspace_id,radar_id,created_at DESC);
CREATE TABLE IF NOT EXISTS decision_eligible_actions (workspace_id text NOT NULL,decision_id text NOT NULL,action_type text NOT NULL,action_version integer NOT NULL,parameters jsonb NOT NULL DEFAULT '{}'::jsonb,PRIMARY KEY(workspace_id,decision_id,action_type),FOREIGN KEY(workspace_id,decision_id) REFERENCES decision_records(workspace_id,id) ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS action_executions (workspace_id text NOT NULL,id text NOT NULL,decision_id text NOT NULL,action_type text NOT NULL,action_version integer NOT NULL,connection_id text,correlation_id text NOT NULL,idempotency_key text NOT NULL,status text NOT NULL,remote_id text,counts jsonb NOT NULL DEFAULT '{}'::jsonb,failure_category text,attempts integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,id),UNIQUE(workspace_id,idempotency_key),FOREIGN KEY(workspace_id,decision_id) REFERENCES decision_records(workspace_id,id) ON DELETE RESTRICT,CHECK(status IN ('queued','attempting','succeeded','partially_succeeded','failed','unknown','cancelled')));
CREATE INDEX IF NOT EXISTS action_executions_decision_idx ON action_executions(workspace_id,decision_id);
CREATE TABLE IF NOT EXISTS exposure_observations (workspace_id text NOT NULL,id text NOT NULL,decision_id text NOT NULL,execution_id text,kind text NOT NULL,source_confidence text NOT NULL,provider_event_id text,occurred_at timestamptz,ingested_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,id),UNIQUE(workspace_id,provider_event_id),FOREIGN KEY(workspace_id,decision_id) REFERENCES decision_records(workspace_id,id) ON DELETE RESTRICT,FOREIGN KEY(workspace_id,execution_id) REFERENCES action_executions(workspace_id,id) ON DELETE RESTRICT,CHECK(kind IN ('sent','delivered','impression','audience_membership_confirmed','unknown','not_observed')));
CREATE TABLE IF NOT EXISTS reward_observations (workspace_id text NOT NULL,id text NOT NULL,decision_id text NOT NULL,version integer NOT NULL,outcome_count integer NOT NULL,observed_value numeric,currency text,first_outcome_at timestamptz,last_outcome_at timestamptz,final boolean NOT NULL DEFAULT false,reward_function_version text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,id),UNIQUE(workspace_id,decision_id,version),FOREIGN KEY(workspace_id,decision_id) REFERENCES decision_records(workspace_id,id) ON DELETE RESTRICT,CHECK(outcome_count>=0));
